package com.clavis.reader;
import java.util.*;import java.util.regex.*;
/** Match native rendered words to semantic narration without assuming identical line wrapping. */
final class NarrationIndex {
 static final class Token {final String word,raw;final int start,end;Token(String raw,int start,int end){this.raw=raw;this.word=normal(raw);this.start=start;this.end=end;}}
 final ArrayList<Token> words=new ArrayList<>();final HashMap<String,ArrayList<Integer>> anchors=new HashMap<>();
 NarrationIndex(String text){Matcher m=Pattern.compile("\\S+").matcher(text);while(m.find()){Token t=new Token(m.group(),m.start(),m.end());if(!t.word.isEmpty())words.add(t);}for(int n=0;n+2<words.size();n++)anchors.computeIfAbsent(key(words.get(n).word,words.get(n+1).word,words.get(n+2).word),k->new ArrayList<>()).add(n);}
 static String normal(String value){return java.text.Normalizer.normalize(value,java.text.Normalizer.Form.NFKC).toLowerCase(Locale.US).replace('’','\'').replaceAll("[^\\p{L}\\p{N}']","");}
 static String key(String a,String b,String c){return a+'\u0001'+b+'\u0001'+c;}
 String phrase(int position,int count){int first=0;while(first+1<words.size()&&words.get(first).end<=position)first++;StringBuilder out=new StringBuilder();for(int n=first;n<Math.min(words.size(),first+count);n++){if(out.length()>0)out.append(' ');out.append(words.get(n).raw);}return out.toString();}
 int[] align(List<String> page,int near){int[] result=new int[page.size()];Arrays.fill(result,-1);int best=-1,bestPage=0;double score=-Double.MAX_VALUE;for(int i=0;i+2<page.size();i++){ArrayList<Integer> candidates=anchors.get(key(page.get(i),page.get(i+1),page.get(i+2)));if(candidates==null)continue;int examined=0;for(int at:candidates){if(examined++>100)break;int run=0;while(i+run<page.size()&&at+run<words.size()&&page.get(i+run).equals(words.get(at+run).word))run++;double quality=run*1000.0-Math.abs(words.get(at).start-near)/100.0;if(quality>score){score=quality;best=at;bestPage=i;}}}if(best<0){if(page.size()>2)return result;for(int at=0;at<words.size();at++){int run=0;while(run<page.size()&&at+run<words.size()&&page.get(run).equals(words.get(at+run).word))run++;double quality=run*1000.0-Math.abs(words.get(at).start-near)/100.0;if(run>0&&quality>score){score=quality;best=at;bestPage=0;}}}if(best<0)return result;int anchorLength=Math.min(3,Math.min(page.size()-bestPage,words.size()-best));for(int k=0;k<anchorLength;k++)result[bestPage+k]=best+k;alignRange(page,result,0,bestPage,Math.max(0,best-bestPage-20),best);alignRange(page,result,bestPage+anchorLength,page.size(),best+anchorLength,Math.min(words.size(),best+page.size()-bestPage+40));return result;}
 void alignRange(List<String> page,int[] result,int pageStart,int pageEnd,int from,int until){int n=pageEnd-pageStart,m=until-from;if(n<=0||m<=0)return;int[][] dp=new int[n+1][m+1];for(int i=n-1;i>=0;i--)for(int j=m-1;j>=0;j--)dp[i][j]=page.get(pageStart+i).equals(words.get(from+j).word)?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);int i=0,j=0;while(i<n&&j<m){if(page.get(pageStart+i).equals(words.get(from+j).word)){result[pageStart+i++]=from+j++;}else if(dp[i+1][j]>=dp[i][j+1])i++;else j++;}}

}
